package com.simon.mytasks;
public class ComposerHingeTest{public static void main(String[] x){int[] v=ComposerLayoutPolicy.usablePane(1200,900,590,0,610,900);if(v[0]!=0||v[2]!=590)throw new AssertionError("vertical hinge must not be spanned");int[] h=ComposerLayoutPolicy.usablePane(900,1200,0,450,900,470);if(h[1]!=470||h[3]!=730)throw new AssertionError("horizontal hinge choose useful pane");int[] none=ComposerLayoutPolicy.usablePane(900,1200,0,0,0,0);if(!ComposerLayoutPolicy.splitAroundHinge(1200,900,590,0,610,900,1,false)||ComposerLayoutPolicy.splitAroundHinge(900,1200,0,450,900,470,1,false))throw new AssertionError("vertical hinge split only when actual panes readable");if(none[2]!=900||none[3]!=1200)throw new AssertionError();if(!ComposerLayoutPolicy.split(809,1,false,0)||ComposerLayoutPolicy.split(720,1,false,0)||ComposerLayoutPolicy.split(809,1.3f,false,0))throw new AssertionError("measured inner 809dp must split; narrow/scaled falls back");System.out.println("ComposerHingeTest passed");}}
